-- =====================================================================================================================================
-- manual_seed_four_synthetic_clients.sql
--
-- PURPOSE   Insert the four SYNTHETIC client configurations (SYN-CLIENT-A .. SYN-CLIENT-D) into the Supabase DEVELOPMENT database: 207 rows
--           across seven existing tables. Generated from client_configuration/profiles/client_[a-d]_config.json by
--           client_configuration/generate_manual_seed_sql.py (the same projection the Python seeder's dry run uses).
--
-- WARNING   DEVELOPMENT ONLY. Do NOT run this against Production. Every value is a labelled synthetic test assumption, not an approved client policy.
--           It contains no secrets, no personal data and no real client data. It does not touch role_access_matrix (UC-04 has not confirmed that
--           projection) and it creates no table, column or index.
--
-- BEHAVIOUR One transaction. It INSERTs only; it never UPDATEs, DELETEs or TRUNCATEs, and it never overwrites. It refuses to run if any row already exists for
--           the four client ids. Every INSERT also carries a NOT EXISTS guard on the natural key, and a final assertion block RAISEs an EXCEPTION (so the whole
--           transaction rolls back) if any row was skipped or any reference is wrong. Nothing is ignored silently.
--
-- HOW TO RUN Paste the whole file into the Supabase SQL editor of the DEVELOPMENT project (role postgres). Read the pre-insert queries (section 1) first; run
--           sections 2-5 together. If anything fails, nothing is committed. See manual_seed_four_synthetic_clients_README.md.
--
-- EXPECTED INSERTS
--   client_configs                   4   A=1  B=1  C=1  D=1
--   client_config_versions           4   A=1  B=1  C=1  D=1
--   task_templates                  57   A=15  B=11  C=15  D=16
--   client_document_requirements    55   A=13  B=12  C=17  D=13
--   client_service_policies         74   A=20  B=15  C=18  D=21
--   client_milestone_templates       4   A=1  B=1  C=1  D=1
--   client_holidays                  9   A=2  B=2  C=3  D=2
--   TOTAL                          207
--
-- DUPLICATE-PREVENTION KEYS
--   client_configs (client_id) | client_config_versions (client_id, version) | task_templates (client_id, template_key)  <- the live PRIMARY KEY has no config_version
--   client_document_requirements (client_id, config_version, requirement_key) | client_service_policies (client_id, config_version, service_category, service_key)
--   client_milestone_templates (client_id, config_version, milestone_key) | client_holidays (client_id, holiday_date)
--   Per the schema exports, client_document_requirements and client_milestone_templates have UNIQUE (client_id, config_version, key) and, with client_service_policies, a composite
--   foreign key (client_id, config_version) -> client_config_versions(client_id, version). client_service_policies' own PK/UNIQUE was not in the (truncated) export, so these checks plus a
--   table lock are the protection there (see the README for the concurrency limitation).
-- =====================================================================================================================================

-- =====================================================================================================================================
-- SECTION 1. PRE-INSERT VERIFICATION (read-only SELECTs; run these first and read the results)
-- =====================================================================================================================================

-- 1a. Rows that already exist for the four client ids. EXPECTED: 0 for every table.
SELECT 'client_configs' AS table_name, count(*) AS rows_for_the_four_clients FROM public.client_configs WHERE client_id IN ('SYN-CLIENT-A', 'SYN-CLIENT-B', 'SYN-CLIENT-C', 'SYN-CLIENT-D')
UNION ALL
SELECT 'client_config_versions' AS table_name, count(*) AS rows_for_the_four_clients FROM public.client_config_versions WHERE client_id IN ('SYN-CLIENT-A', 'SYN-CLIENT-B', 'SYN-CLIENT-C', 'SYN-CLIENT-D')
UNION ALL
SELECT 'task_templates' AS table_name, count(*) AS rows_for_the_four_clients FROM public.task_templates WHERE client_id IN ('SYN-CLIENT-A', 'SYN-CLIENT-B', 'SYN-CLIENT-C', 'SYN-CLIENT-D')
UNION ALL
SELECT 'client_document_requirements' AS table_name, count(*) AS rows_for_the_four_clients FROM public.client_document_requirements WHERE client_id IN ('SYN-CLIENT-A', 'SYN-CLIENT-B', 'SYN-CLIENT-C', 'SYN-CLIENT-D')
UNION ALL
SELECT 'client_service_policies' AS table_name, count(*) AS rows_for_the_four_clients FROM public.client_service_policies WHERE client_id IN ('SYN-CLIENT-A', 'SYN-CLIENT-B', 'SYN-CLIENT-C', 'SYN-CLIENT-D')
UNION ALL
SELECT 'client_milestone_templates' AS table_name, count(*) AS rows_for_the_four_clients FROM public.client_milestone_templates WHERE client_id IN ('SYN-CLIENT-A', 'SYN-CLIENT-B', 'SYN-CLIENT-C', 'SYN-CLIENT-D')
UNION ALL
SELECT 'client_holidays' AS table_name, count(*) AS rows_for_the_four_clients FROM public.client_holidays WHERE client_id IN ('SYN-CLIENT-A', 'SYN-CLIENT-B', 'SYN-CLIENT-C', 'SYN-CLIENT-D');

-- 1b. Current total rows per table (for your records; the seed adds the counts in the header).
SELECT 'client_configs' AS table_name, count(*) AS total_rows_now FROM public.client_configs
UNION ALL
SELECT 'client_config_versions' AS table_name, count(*) AS total_rows_now FROM public.client_config_versions
UNION ALL
SELECT 'task_templates' AS table_name, count(*) AS total_rows_now FROM public.task_templates
UNION ALL
SELECT 'client_document_requirements' AS table_name, count(*) AS total_rows_now FROM public.client_document_requirements
UNION ALL
SELECT 'client_service_policies' AS table_name, count(*) AS total_rows_now FROM public.client_service_policies
UNION ALL
SELECT 'client_milestone_templates' AS table_name, count(*) AS total_rows_now FROM public.client_milestone_templates
UNION ALL
SELECT 'client_holidays' AS table_name, count(*) AS total_rows_now FROM public.client_holidays;

-- 1c. Client ids already present (the four SYN-CLIENT ids must NOT appear here).
SELECT client_id, company_name, is_active FROM public.client_configs ORDER BY client_id;

-- 1d. The primary keys and foreign keys actually present on the seven tables (so you can compare with the README).
SELECT conrelid::regclass AS table_name, conname, contype AS kind, pg_get_constraintdef(oid) AS definition
FROM pg_constraint
WHERE conrelid IN ('public.client_configs'::regclass, 'public.client_config_versions'::regclass, 'public.task_templates'::regclass, 'public.client_document_requirements'::regclass, 'public.client_service_policies'::regclass, 'public.client_milestone_templates'::regclass, 'public.client_holidays'::regclass) AND contype IN ('p', 'f', 'u')
ORDER BY conrelid::regclass::text, contype, conname;

-- =====================================================================================================================================
-- SECTION 2. TRANSACTION, LOCKS AND GUARDS
-- =====================================================================================================================================
BEGIN;

-- Serialise concurrent writers on the three versioned tables (reads are still allowed). Needed most for client_service_policies, whose unique constraint is unconfirmed. Released at COMMIT / ROLLBACK.
LOCK TABLE public.client_document_requirements, public.client_service_policies, public.client_milestone_templates IN SHARE ROW EXCLUSIVE MODE;

-- Guard 1: the live schema still has every column this script supplies and no NOT NULL-without-default column it does not supply.
DO $guard$
DECLARE
  spec record;
  missing text;
  unsupplied text;
BEGIN
  FOR spec IN SELECT * FROM (VALUES
      ('client_configs', ARRAY['client_id', 'company_name', 'config_hash', 'working_days', 'timezone', 'template_count', 'milestone_count', 'settings_payload', 'is_active']),
      ('client_config_versions', ARRAY['client_id', 'version', 'effective_from', 'effective_to', 'status', 'config_hash', 'approved_by', 'approved_at']),
      ('task_templates', ARRAY['template_key', 'client_id', 'category', 'title', 'title_ar', 'owner_role', 'default_lead_days', 'evidence_required', 'requires_attributes', 'sensitive_to', 'approval_role', 'description', 'role_ids', 'grades', 'locations', 'projects', 'nationality_groups', 'depends_on_template_keys', 'offset_days', 'default_priority', 'config_version', 'is_active']),
      ('client_document_requirements', ARRAY['requirement_id', 'client_id', 'config_version', 'service_category', 'requirement_key', 'document_type', 'description', 'is_mandatory', 'applicable_roles', 'applicable_grades', 'applicable_locations', 'applicable_projects', 'eligibility_rules', 'validation_profile', 'is_active']),
      ('client_service_policies', ARRAY['policy_id', 'client_id', 'config_version', 'service_category', 'service_key', 'is_available', 'is_mandatory', 'eligibility_rules', 'policy_details', 'responsible_role', 'effective_from', 'effective_to', 'is_active']),
      ('client_milestone_templates', ARRAY['milestone_id', 'client_id', 'config_version', 'milestone_key', 'title', 'offset_days', 'required_task_keys', 'eligibility_rules', 'is_active']),
      ('client_holidays', ARRAY['client_id', 'holiday_date', 'name', 'is_observed'])
  ) AS s(tbl, supplied) LOOP
    SELECT string_agg(c, ', ') INTO missing FROM unnest(spec.supplied) AS c
      WHERE NOT EXISTS (SELECT 1 FROM information_schema.columns ic
                        WHERE ic.table_schema = 'public' AND ic.table_name = spec.tbl AND ic.column_name = c);
    IF missing IS NOT NULL THEN
      RAISE EXCEPTION 'schema drift: public.% is missing column(s): %', spec.tbl, missing;
    END IF;
    SELECT string_agg(ic.column_name, ', ') INTO unsupplied FROM information_schema.columns ic
      WHERE ic.table_schema = 'public' AND ic.table_name = spec.tbl AND ic.is_nullable = 'NO' AND ic.column_default IS NULL
        AND ic.column_name <> ALL (spec.supplied);
    IF unsupplied IS NOT NULL THEN
      RAISE EXCEPTION 'schema drift: public.% has NOT NULL column(s) without a default that this script does not supply: %', spec.tbl, unsupplied;
    END IF;
  END LOOP;
END
$guard$;

-- Guard 2: first-time seed only. Refuses to run if any row already exists for the four client ids.
DO $guard$
DECLARE
  existing bigint;
BEGIN
  SELECT (SELECT count(*) FROM public.client_configs WHERE client_id IN ('SYN-CLIENT-A', 'SYN-CLIENT-B', 'SYN-CLIENT-C', 'SYN-CLIENT-D'))
    + (SELECT count(*) FROM public.client_config_versions WHERE client_id IN ('SYN-CLIENT-A', 'SYN-CLIENT-B', 'SYN-CLIENT-C', 'SYN-CLIENT-D'))
    + (SELECT count(*) FROM public.task_templates WHERE client_id IN ('SYN-CLIENT-A', 'SYN-CLIENT-B', 'SYN-CLIENT-C', 'SYN-CLIENT-D'))
    + (SELECT count(*) FROM public.client_document_requirements WHERE client_id IN ('SYN-CLIENT-A', 'SYN-CLIENT-B', 'SYN-CLIENT-C', 'SYN-CLIENT-D'))
    + (SELECT count(*) FROM public.client_service_policies WHERE client_id IN ('SYN-CLIENT-A', 'SYN-CLIENT-B', 'SYN-CLIENT-C', 'SYN-CLIENT-D'))
    + (SELECT count(*) FROM public.client_milestone_templates WHERE client_id IN ('SYN-CLIENT-A', 'SYN-CLIENT-B', 'SYN-CLIENT-C', 'SYN-CLIENT-D'))
    + (SELECT count(*) FROM public.client_holidays WHERE client_id IN ('SYN-CLIENT-A', 'SYN-CLIENT-B', 'SYN-CLIENT-C', 'SYN-CLIENT-D')) INTO existing;
  IF existing <> 0 THEN
    RAISE EXCEPTION 'refusing to run: % row(s) already exist for the four SYN-CLIENT ids. This script is a first-time seed and never overwrites, updates or deletes.', existing;
  END IF;
END
$guard$;

