-- =====================================================================================================================================
-- SECTION 4. IN-TRANSACTION ASSERTIONS (any failure RAISEs and rolls the whole seed back)
-- =====================================================================================================================================
DO $verify$
DECLARE
  bad text;
BEGIN
  -- 1. exact row counts per table and client
  SELECT string_agg(e.tbl || '/' || e.client || ': expected ' || e.expected || ' found ' || a.n, '; ') INTO bad
  FROM (VALUES
      ('client_configs', 'SYN-CLIENT-A', 1),
      ('client_configs', 'SYN-CLIENT-B', 1),
      ('client_configs', 'SYN-CLIENT-C', 1),
      ('client_configs', 'SYN-CLIENT-D', 1),
      ('client_config_versions', 'SYN-CLIENT-A', 1),
      ('client_config_versions', 'SYN-CLIENT-B', 1),
      ('client_config_versions', 'SYN-CLIENT-C', 1),
      ('client_config_versions', 'SYN-CLIENT-D', 1),
      ('task_templates', 'SYN-CLIENT-A', 15),
      ('task_templates', 'SYN-CLIENT-B', 11),
      ('task_templates', 'SYN-CLIENT-C', 15),
      ('task_templates', 'SYN-CLIENT-D', 16),
      ('client_document_requirements', 'SYN-CLIENT-A', 13),
      ('client_document_requirements', 'SYN-CLIENT-B', 12),
      ('client_document_requirements', 'SYN-CLIENT-C', 17),
      ('client_document_requirements', 'SYN-CLIENT-D', 13),
      ('client_service_policies', 'SYN-CLIENT-A', 20),
      ('client_service_policies', 'SYN-CLIENT-B', 15),
      ('client_service_policies', 'SYN-CLIENT-C', 18),
      ('client_service_policies', 'SYN-CLIENT-D', 21),
      ('client_milestone_templates', 'SYN-CLIENT-A', 1),
      ('client_milestone_templates', 'SYN-CLIENT-B', 1),
      ('client_milestone_templates', 'SYN-CLIENT-C', 1),
      ('client_milestone_templates', 'SYN-CLIENT-D', 1),
      ('client_holidays', 'SYN-CLIENT-A', 2),
      ('client_holidays', 'SYN-CLIENT-B', 2),
      ('client_holidays', 'SYN-CLIENT-C', 3),
      ('client_holidays', 'SYN-CLIENT-D', 2)
  ) AS e(tbl, client, expected)
  JOIN LATERAL (
    SELECT CASE e.tbl
      WHEN 'client_configs' THEN (SELECT count(*) FROM public.client_configs WHERE client_id = e.client)
      WHEN 'client_config_versions' THEN (SELECT count(*) FROM public.client_config_versions WHERE client_id = e.client)
      WHEN 'task_templates' THEN (SELECT count(*) FROM public.task_templates WHERE client_id = e.client)
      WHEN 'client_document_requirements' THEN (SELECT count(*) FROM public.client_document_requirements WHERE client_id = e.client)
      WHEN 'client_service_policies' THEN (SELECT count(*) FROM public.client_service_policies WHERE client_id = e.client)
      WHEN 'client_milestone_templates' THEN (SELECT count(*) FROM public.client_milestone_templates WHERE client_id = e.client)
      WHEN 'client_holidays' THEN (SELECT count(*) FROM public.client_holidays WHERE client_id = e.client)
    END AS n) a ON TRUE
  WHERE a.n <> e.expected;
  IF bad IS NOT NULL THEN RAISE EXCEPTION 'row count mismatch (a duplicate-prevention check skipped a row, or a row failed): %', bad; END IF;

  -- 2. every child row's client exists in client_configs
  IF EXISTS (SELECT 1 FROM public.client_config_versions c WHERE c.client_id IN ('SYN-CLIENT-A', 'SYN-CLIENT-B', 'SYN-CLIENT-C', 'SYN-CLIENT-D') AND NOT EXISTS (SELECT 1 FROM public.client_configs p WHERE p.client_id = c.client_id))
     OR EXISTS (SELECT 1 FROM public.task_templates c WHERE c.client_id IN ('SYN-CLIENT-A', 'SYN-CLIENT-B', 'SYN-CLIENT-C', 'SYN-CLIENT-D') AND NOT EXISTS (SELECT 1 FROM public.client_configs p WHERE p.client_id = c.client_id))
     OR EXISTS (SELECT 1 FROM public.client_document_requirements c WHERE c.client_id IN ('SYN-CLIENT-A', 'SYN-CLIENT-B', 'SYN-CLIENT-C', 'SYN-CLIENT-D') AND NOT EXISTS (SELECT 1 FROM public.client_configs p WHERE p.client_id = c.client_id))
     OR EXISTS (SELECT 1 FROM public.client_service_policies c WHERE c.client_id IN ('SYN-CLIENT-A', 'SYN-CLIENT-B', 'SYN-CLIENT-C', 'SYN-CLIENT-D') AND NOT EXISTS (SELECT 1 FROM public.client_configs p WHERE p.client_id = c.client_id))
     OR EXISTS (SELECT 1 FROM public.client_milestone_templates c WHERE c.client_id IN ('SYN-CLIENT-A', 'SYN-CLIENT-B', 'SYN-CLIENT-C', 'SYN-CLIENT-D') AND NOT EXISTS (SELECT 1 FROM public.client_configs p WHERE p.client_id = c.client_id))
     OR EXISTS (SELECT 1 FROM public.client_holidays c WHERE c.client_id IN ('SYN-CLIENT-A', 'SYN-CLIENT-B', 'SYN-CLIENT-C', 'SYN-CLIENT-D') AND NOT EXISTS (SELECT 1 FROM public.client_configs p WHERE p.client_id = c.client_id))
  THEN RAISE EXCEPTION 'a child row references a client with no client_configs row'; END IF;

  -- 3. every versioned child row points at an existing client_config_versions row
  IF EXISTS (SELECT 1 FROM public.task_templates c WHERE c.client_id IN ('SYN-CLIENT-A', 'SYN-CLIENT-B', 'SYN-CLIENT-C', 'SYN-CLIENT-D') AND NOT EXISTS (SELECT 1 FROM public.client_config_versions v WHERE v.client_id = c.client_id AND v.version = c.config_version))
     OR EXISTS (SELECT 1 FROM public.client_document_requirements c WHERE c.client_id IN ('SYN-CLIENT-A', 'SYN-CLIENT-B', 'SYN-CLIENT-C', 'SYN-CLIENT-D') AND NOT EXISTS (SELECT 1 FROM public.client_config_versions v WHERE v.client_id = c.client_id AND v.version = c.config_version))
     OR EXISTS (SELECT 1 FROM public.client_service_policies c WHERE c.client_id IN ('SYN-CLIENT-A', 'SYN-CLIENT-B', 'SYN-CLIENT-C', 'SYN-CLIENT-D') AND NOT EXISTS (SELECT 1 FROM public.client_config_versions v WHERE v.client_id = c.client_id AND v.version = c.config_version))
     OR EXISTS (SELECT 1 FROM public.client_milestone_templates c WHERE c.client_id IN ('SYN-CLIENT-A', 'SYN-CLIENT-B', 'SYN-CLIENT-C', 'SYN-CLIENT-D') AND NOT EXISTS (SELECT 1 FROM public.client_config_versions v WHERE v.client_id = c.client_id AND v.version = c.config_version))
  THEN RAISE EXCEPTION 'a versioned row references a configuration version that does not exist'; END IF;

  -- 4. no duplicate natural keys (belt and braces: the live schema has UNIQUE (client_id, config_version, key) on documents and milestones; client_service_policies' own unique constraint was not in the schema export)
  IF EXISTS (SELECT 1 FROM public.client_configs WHERE client_id IN ('SYN-CLIENT-A', 'SYN-CLIENT-B', 'SYN-CLIENT-C', 'SYN-CLIENT-D') GROUP BY client_id HAVING count(*) > 1)
     OR EXISTS (SELECT 1 FROM public.client_config_versions WHERE client_id IN ('SYN-CLIENT-A', 'SYN-CLIENT-B', 'SYN-CLIENT-C', 'SYN-CLIENT-D') GROUP BY client_id, version HAVING count(*) > 1)
     OR EXISTS (SELECT 1 FROM public.task_templates WHERE client_id IN ('SYN-CLIENT-A', 'SYN-CLIENT-B', 'SYN-CLIENT-C', 'SYN-CLIENT-D') GROUP BY client_id, template_key HAVING count(*) > 1)
     OR EXISTS (SELECT 1 FROM public.client_document_requirements WHERE client_id IN ('SYN-CLIENT-A', 'SYN-CLIENT-B', 'SYN-CLIENT-C', 'SYN-CLIENT-D') GROUP BY client_id, config_version, requirement_key HAVING count(*) > 1)
     OR EXISTS (SELECT 1 FROM public.client_service_policies WHERE client_id IN ('SYN-CLIENT-A', 'SYN-CLIENT-B', 'SYN-CLIENT-C', 'SYN-CLIENT-D') GROUP BY client_id, config_version, service_category, service_key HAVING count(*) > 1)
     OR EXISTS (SELECT 1 FROM public.client_milestone_templates WHERE client_id IN ('SYN-CLIENT-A', 'SYN-CLIENT-B', 'SYN-CLIENT-C', 'SYN-CLIENT-D') GROUP BY client_id, config_version, milestone_key HAVING count(*) > 1)
     OR EXISTS (SELECT 1 FROM public.client_holidays WHERE client_id IN ('SYN-CLIENT-A', 'SYN-CLIENT-B', 'SYN-CLIENT-C', 'SYN-CLIENT-D') GROUP BY client_id, holiday_date HAVING count(*) > 1)
  THEN RAISE EXCEPTION 'duplicate natural key found'; END IF;

  -- 5. task dependencies and milestone requirements point at templates of the same client
  SELECT string_agg(t.client_id || ':' || t.template_key || '->' || d, '; ') INTO bad
  FROM public.task_templates t, unnest(t.depends_on_template_keys) AS d
  WHERE t.client_id IN ('SYN-CLIENT-A', 'SYN-CLIENT-B', 'SYN-CLIENT-C', 'SYN-CLIENT-D')
    AND NOT EXISTS (SELECT 1 FROM public.task_templates x WHERE x.client_id = t.client_id AND x.template_key = d);
  IF bad IS NOT NULL THEN RAISE EXCEPTION 'task depends on an unknown template: %', bad; END IF;
  SELECT string_agg(m.client_id || ':' || m.milestone_key || '->' || k, '; ') INTO bad
  FROM public.client_milestone_templates m, unnest(m.required_task_keys) AS k
  WHERE m.client_id IN ('SYN-CLIENT-A', 'SYN-CLIENT-B', 'SYN-CLIENT-C', 'SYN-CLIENT-D')
    AND NOT EXISTS (SELECT 1 FROM public.task_templates x WHERE x.client_id = m.client_id AND x.template_key = k);
  IF bad IS NOT NULL THEN RAISE EXCEPTION 'milestone requires an unknown template: %', bad; END IF;

  -- 6. version and client agree on the document hash; approved versions carry approver and timestamp
  IF EXISTS (SELECT 1 FROM public.client_config_versions v JOIN public.client_configs c ON c.client_id = v.client_id
             WHERE v.client_id IN ('SYN-CLIENT-A', 'SYN-CLIENT-B', 'SYN-CLIENT-C', 'SYN-CLIENT-D') AND v.config_hash <> c.config_hash)
     OR EXISTS (SELECT 1 FROM public.client_config_versions WHERE client_id IN ('SYN-CLIENT-A', 'SYN-CLIENT-B', 'SYN-CLIENT-C', 'SYN-CLIENT-D') AND status = 'approved' AND (approved_by IS NULL OR approved_at IS NULL))
  THEN RAISE EXCEPTION 'configuration version metadata is inconsistent'; END IF;

  -- 7. the data is marked synthetic
  IF EXISTS (SELECT 1 FROM public.client_configs WHERE client_id IN ('SYN-CLIENT-A', 'SYN-CLIENT-B', 'SYN-CLIENT-C', 'SYN-CLIENT-D') AND settings_payload ->> 'data_origin' IS DISTINCT FROM 'synthetic')
  THEN RAISE EXCEPTION 'a seeded client is not marked synthetic'; END IF;

  RAISE NOTICE 'seed verified: 207 rows, 4 clients, no duplicates, no missing references';
END
$verify$;

COMMIT;

