    ('task_templates', 'SYN-CLIENT-D', 16),
    ('client_document_requirements', 'SYN-CLIENT-A', 13),
    ('client_document_requirements', 'SYN-CLIENT-B', 12),
    ('client_document_requirements', 'SYN-CLIENT-C', 17),
    ('client_document_requirements', 'SYN-CLIENT-D', 13),
    ('client_service_policies', 'SYN-CLIENT-A', 20),
    ('client_service_policies', 'SYN-CLIENT-B', 15),
    ('client_service_policies', 'SYN-CLIENT-C', 18),
    ('client_service_policies', 'SYN-CLIENT-D', 21),
    ('client_milestone_templates', 'SYN-CLIENT-A', 1),
    ('client_milestone_templates', 'SYN-CLIENT-B', 1),
    ('client_milestone_templates', 'SYN-CLIENT-C', 1),
    ('client_milestone_templates', 'SYN-CLIENT-D', 1),
    ('client_holidays', 'SYN-CLIENT-A', 2),
    ('client_holidays', 'SYN-CLIENT-B', 2),
    ('client_holidays', 'SYN-CLIENT-C', 3),
    ('client_holidays', 'SYN-CLIENT-D', 2)
) AS e(tbl, client, expected)
JOIN LATERAL (
  SELECT CASE e.tbl
      WHEN 'client_configs' THEN (SELECT count(*) FROM public.client_configs WHERE client_id = e.client)
      WHEN 'client_config_versions' THEN (SELECT count(*) FROM public.client_config_versions WHERE client_id = e.client)
      WHEN 'task_templates' THEN (SELECT count(*) FROM public.task_templates WHERE client_id = e.client)
      WHEN 'client_document_requirements' THEN (SELECT count(*) FROM public.client_document_requirements WHERE client_id = e.client)
      WHEN 'client_service_policies' THEN (SELECT count(*) FROM public.client_service_policies WHERE client_id = e.client)
      WHEN 'client_milestone_templates' THEN (SELECT count(*) FROM public.client_milestone_templates WHERE client_id = e.client)
      WHEN 'client_holidays' THEN (SELECT count(*) FROM public.client_holidays WHERE client_id = e.client)
  END AS n) a ON TRUE
ORDER BY e.tbl, e.client;

-- 5b. Grand total across the seven tables for the four clients. EXPECTED: 207.
SELECT sum(n) AS total_rows_seeded FROM (
SELECT 'client_configs' AS tbl, count(*) AS n FROM public.client_configs WHERE client_id IN ('SYN-CLIENT-A', 'SYN-CLIENT-B', 'SYN-CLIENT-C', 'SYN-CLIENT-D')
UNION ALL
SELECT 'client_config_versions' AS tbl, count(*) AS n FROM public.client_config_versions WHERE client_id IN ('SYN-CLIENT-A', 'SYN-CLIENT-B', 'SYN-CLIENT-C', 'SYN-CLIENT-D')
UNION ALL
SELECT 'task_templates' AS tbl, count(*) AS n FROM public.task_templates WHERE client_id IN ('SYN-CLIENT-A', 'SYN-CLIENT-B', 'SYN-CLIENT-C', 'SYN-CLIENT-D')
UNION ALL
SELECT 'client_document_requirements' AS tbl, count(*) AS n FROM public.client_document_requirements WHERE client_id IN ('SYN-CLIENT-A', 'SYN-CLIENT-B', 'SYN-CLIENT-C', 'SYN-CLIENT-D')
UNION ALL
SELECT 'client_service_policies' AS tbl, count(*) AS n FROM public.client_service_policies WHERE client_id IN ('SYN-CLIENT-A', 'SYN-CLIENT-B', 'SYN-CLIENT-C', 'SYN-CLIENT-D')
UNION ALL
SELECT 'client_milestone_templates' AS tbl, count(*) AS n FROM public.client_milestone_templates WHERE client_id IN ('SYN-CLIENT-A', 'SYN-CLIENT-B', 'SYN-CLIENT-C', 'SYN-CLIENT-D')
UNION ALL
SELECT 'client_holidays' AS tbl, count(*) AS n FROM public.client_holidays WHERE client_id IN ('SYN-CLIENT-A', 'SYN-CLIENT-B', 'SYN-CLIENT-C', 'SYN-CLIENT-D')
) s;

-- 5c. Each client and its configuration version.
SELECT c.client_id, c.company_name, c.timezone, c.working_days, c.settings_payload ->> 'data_origin' AS data_origin,
       v.version, v.status, v.effective_from, v.effective_to, v.approved_by, (v.config_hash = c.config_hash) AS hash_matches
FROM public.client_configs c JOIN public.client_config_versions v ON v.client_id = c.client_id
WHERE c.client_id IN ('SYN-CLIENT-A', 'SYN-CLIENT-B', 'SYN-CLIENT-C', 'SYN-CLIENT-D') ORDER BY c.client_id;

-- 5d. Child rows whose client or version is missing. EXPECTED: no rows.
SELECT 'task_templates' AS table_name, t.client_id, t.template_key AS key FROM public.task_templates t
  WHERE t.client_id IN ('SYN-CLIENT-A', 'SYN-CLIENT-B', 'SYN-CLIENT-C', 'SYN-CLIENT-D') AND NOT EXISTS (SELECT 1 FROM public.client_config_versions v WHERE v.client_id = t.client_id AND v.version = t.config_version)
UNION ALL SELECT 'client_document_requirements', d.client_id, d.requirement_key FROM public.client_document_requirements d
  WHERE d.client_id IN ('SYN-CLIENT-A', 'SYN-CLIENT-B', 'SYN-CLIENT-C', 'SYN-CLIENT-D') AND NOT EXISTS (SELECT 1 FROM public.client_config_versions v WHERE v.client_id = d.client_id AND v.version = d.config_version)
UNION ALL SELECT 'client_service_policies', p.client_id, p.service_category || '/' || p.service_key FROM public.client_service_policies p
  WHERE p.client_id IN ('SYN-CLIENT-A', 'SYN-CLIENT-B', 'SYN-CLIENT-C', 'SYN-CLIENT-D') AND NOT EXISTS (SELECT 1 FROM public.client_config_versions v WHERE v.client_id = p.client_id AND v.version = p.config_version)
UNION ALL SELECT 'client_milestone_templates', m.client_id, m.milestone_key FROM public.client_milestone_templates m
  WHERE m.client_id IN ('SYN-CLIENT-A', 'SYN-CLIENT-B', 'SYN-CLIENT-C', 'SYN-CLIENT-D') AND NOT EXISTS (SELECT 1 FROM public.client_config_versions v WHERE v.client_id = m.client_id AND v.version = m.config_version);

