UNION ALL SELECT 'client_document_requirements', client_id, requirement_key, count(*) FROM public.client_document_requirements WHERE client_id IN ('SYN-CLIENT-A', 'SYN-CLIENT-B', 'SYN-CLIENT-C', 'SYN-CLIENT-D') GROUP BY client_id, config_version, requirement_key HAVING count(*) > 1
UNION ALL SELECT 'client_service_policies', client_id, service_category || '/' || service_key, count(*) FROM public.client_service_policies WHERE client_id IN ('SYN-CLIENT-A', 'SYN-CLIENT-B', 'SYN-CLIENT-C', 'SYN-CLIENT-D') GROUP BY client_id, config_version, service_category, service_key HAVING count(*) > 1
UNION ALL SELECT 'client_milestone_templates', client_id, milestone_key, count(*) FROM public.client_milestone_templates WHERE client_id IN ('SYN-CLIENT-A', 'SYN-CLIENT-B', 'SYN-CLIENT-C', 'SYN-CLIENT-D') GROUP BY client_id, config_version, milestone_key HAVING count(*) > 1
UNION ALL SELECT 'client_holidays', client_id, holiday_date::text, count(*) FROM public.client_holidays WHERE client_id IN ('SYN-CLIENT-A', 'SYN-CLIENT-B', 'SYN-CLIENT-C', 'SYN-CLIENT-D') GROUP BY client_id, holiday_date HAVING count(*) > 1;

